-- Final initial-frontier batch. Ownership remains in seed07 and runtime state.
-- Legends geography inspires authored districts and enemy roles.
-- Early Great Galactic War: no daughters of Allya/Nightsisters, Paecian colony,
-- Clone Wars destruction, Trade Federation army or later SWTOR story events.
-- Dac routes use walkways and dry, sealed interiors; no diving mechanic is needed.

INSERT INTO npc_templates(code,name,description,kind) VALUES
 ('commenor_cargo_raider','Грабитель торговых грузов','Высматривает слабо охраняемые перевозки на Комменоре. Пользуется складскими проездами и горными объездами, чтобы скрыть добычу от портовой охраны.','humanoid'),
 ('commenor_canyon_stalker','Каньонный хищник','Находит укрытия среди каменных уступов Комменора. Поджидает добычу у узких переправ и оставленных грузовых стоянок.','beast'),
 ('commenor_customs_droid','Взломанный дроид досмотра','Таможенная машина перешла под управление контрабандистов. Вместо проверки перевозок охраняет тайные склады и задерживает любого постороннего силой.','droid'),
 ('commenor_gem_smuggler','Контрабандист самоцветов','Вывозит камни из нелегальных выработок и скупает похищенные ценности. Держит вооружённую охрану на горных маршрутах и лично защищает важные перевалочные пункты.','humanoid'),
 ('ralltiir_tiger','Раллтиирский тигр','Крупный хищник бродит по удалённым склонам и заросшим низинам. Выбирает укрытия у каменоломен, где шум техники заглушает его приближение.','beast'),
 ('ralltiir_vault_raider','Налётчик на хранилища','Участвует в грабежах перевозок и закрытых депозитариев Раллтиира. Использует украденные коды доступа и охраняет убежища своей группы.','humanoid'),
 ('ralltiir_quarry_droid','Сбойный карьерный дроид','Разрезал и перемещал тяжёлые мраморные блоки. Повреждённые датчики заставляют машину расчищать путь даже тогда, когда на нём находятся живые существа.','droid'),
 ('ralltiir_security_automaton','Взломанный сейфовый автомат','Бронированная охранная машина защищает присвоенные грабителями секции. Её новая программа считает любого без бандитского пропуска целью для задержания.','droid'),
 ('humbarine_scrap_raider','Скупщик краденых деталей','Руководит разборкой чужого оборудования в старых районах Хумбарина. Вооружён и не желает оставлять свидетелей работы своих нелегальных мастерских.','humanoid'),
 ('humbarine_welding_droid','Неисправный сварочный дроид','Промышленная машина продолжает работу по повреждённому заданию. Принимает движущиеся объекты за детали, которые нужно немедленно закрепить и обработать.','droid'),
 ('humbarine_tunnel_vermin','Коллекторный хищник','Небольшой агрессивный зверь обитает в тёплых технических полостях. Защищает кормовые участки среди отходов и нападает из кабельных ниш.','beast'),
 ('humbarine_foundry_guardian','Страж литейного цеха','Тяжёлая машина переделана для охраны подпольного производства. Её мощные захваты перекрывают проходы между печами и сборочными линиями.','droid'),
 ('neimoidia_fungus_stalker','Хищник грибных полей','Прячется среди влажных наростов и густых зарослей Неймодии. Подбирается к добыче по узким тропам между заброшенными хозяйственными участками.','beast'),
 ('neimoidia_hive_defender','Страж колонии насекомых','Крупное насекомое охраняет ходы и кладки в тёплой влажной почве. Бросается на нарушителей, приближающихся к гнезду или покинутым питомникам.','beast'),
 ('neimoidia_cargo_thief','Похититель торговых партий','Сбывает украденные припасы через скрытые склады Неймодии. Защищает свои перевалочные дворы и следит за подходами к нелегальным маршрутам.','humanoid'),
 ('neimoidia_harvest_droid','Сбойный уборочный дроид','Ухаживал за грибными хозяйствами и переносил собранный урожай. Перепутанные команды заставляют его хватать движущиеся цели и расчищать занятые проходы.','droid'),
 ('dathomir_rancor','Ранкор','Огромный хищник удерживает обширные угодья среди лесов и скал Датомира. Следы тяжёлых лап предупреждают об опасности задолго до появления самого зверя.','beast'),
 ('dathomir_forest_stalker','Датомирский лесной хищник','Скрывается в густом подлеске и у каменных ложбин. Обходит владения более крупных зверей и преследует добычу по тесным заросшим тропам.','beast'),
 ('dathomir_relic_poacher','Браконьер-расхититель','Прибыл на Датомир ради редких зверей и древних находок. Ставит ловушки, присваивает чужие раскопы и не допускает свидетелей к своим грузам.','humanoid'),
 ('dathomir_expedition_droid','Повреждённый экспедиционный дроид','Брошенная исследовательская машина сохранила программу защиты стоянки. Сбойные датчики расширили её охраняемый участок на ближайшие тропы и руины.','droid'),
 ('saleucami_crater_stalker','Кратерный хищник','Обитает у воды и среди плотной растительности в кратерах Салукемая. Нападает из укрытия, используя резкие переходы между зарослями и каменными стенами.','beast'),
 ('saleucami_oasis_raider','Налётчик оазисных дорог','Грабит небольшие караваны между поселениями Салукемая. Знает укрытые от жары стоянки и охраняет тайники с похищенными припасами.','humanoid'),
 ('saleucami_thermal_droid','Сбойный термальный дроид','Обслуживал скважины и горячие трубопроводы. После потери управления применяет тяжёлые инструменты против любого объекта, мешающего заданному маршруту.','droid'),
 ('saleucami_gang_overseer','Главарь кратерной банды','Объединил несколько отрядов перехватчиков грузов. Укрепляет захваченные промышленные узлы и держит под охраной пути между оазисами.','humanoid'),
 ('sriluur_dune_hunter','Хищник каменистых пустошей','Находит добычу среди сухих каньонов и затенённых гряд Шрилуура. Долго остаётся неподвижным в укрытии, а затем бросается к оказавшемуся рядом путнику.','beast'),
 ('sriluur_caravan_bandit','Разбойник караванных путей','Участвует в налётах на торговые перевозки Шрилуура. Прячет добычу в скальных нишах и следит за дорогами из укрытий среди тёмного камня.','humanoid'),
 ('sriluur_smelter_droid','Неисправный плавильный дроид','Работал с рудой и раскалённым металлом на удалённых промыслах. Повреждённая система управления превратила его рабочую зону в опасный участок.','droid'),
 ('sriluur_raider_captain','Атаман пустынных налётчиков','Командует вооружённой группой у дальних торговых маршрутов. Использует захваченные мастерские и технику для укрепления своих пустынных убежищ.','humanoid'),
 ('dac_amphibious_predator','Прибрежный хищник Дака','Охотится у рифов и выбирается на низкие влажные настилы. Пользуется приливом, чтобы добраться до грузовых площадок и укрыться под опорами.','beast'),
 ('dac_platform_raider','Налётчик океанских платформ','Захватывает грузы на удалённых причалах и подъёмных станциях. Хорошо знает сухие служебные переходы и защищает присвоенные склады.','humanoid'),
 ('dac_salvage_droid','Повреждённый подъёмный дроид','Переносил тяжёлые находки с морского дна в сухие ремонтные отсеки. Сбой опознавания заставляет его хватать всё, что движется рядом с грузовыми захватами.','droid'),
 ('dac_pressure_warden','Страж герметичных отсеков','Бронированный автомат охраняет шлюзы захваченной океанской станции. Выполняет изменённые команды допуска и блокирует путь к внутренним складам.','droid')
ON CONFLICT (code) DO NOTHING;

-- Republic holdings: Commenor, Ralltiir, Humbarine and Neimoidia.
INSERT INTO locations(planet_id,code,name,description,position,recommended_level)
SELECT p.id,v.code,v.name,v.description,v.position,v.recommended_level FROM (VALUES
 ('commenor','freight_apron','Грузовая посадочная площадка','Широкие опоры принимают торговые суда с ближних маршрутов. За ограждением зоны досмотра начинаются склады, где потерянный груз редко возвращается владельцу.',1,1),
 ('commenor','warehouse_lanes','Складские переулки','Узкие проезды разделяют ряды грузовых ангаров. Переставленные контейнеры скрывают нелегальные перевалочные пункты и засады на перевозчиков.',2,6),
 ('commenor','valley_road','Дорога через долину','Каменная дорога уходит от портовых кварталов к внутренним поселениям. Заросшие ответвления позволяют налётчикам обходить контрольные посты.',3,11),
 ('commenor','canyon_crossing','Каньонные переправы','Грузовые мосты пересекают несколько глубоких расселин. Под опорами прячутся звери, а заброшенные пункты взимания пошлины заняли вооружённые вымогатели.',4,16),
 ('commenor','gem_workings','Старые самоцветные выработки','Уходящие в гору штольни соединены вырубленными в скале площадками. Скупщики нелегальных камней держат здесь тайные склады и собственную охрану.',5,21),
 ('commenor','closed_customs','Закрытый таможенный узел','В опустевших залах досмотра остались сканеры и грузовые захваты. Кто-то изменил пропуска охранных машин, превратив старый терминал в убежище контрабандистов.',6,26),
 ('commenor','ridge_depots','Склады горного хребта','Цепочка хранилищ тянется вдоль узкой дороги над долиной. Уцелевшие подъёмники доставляют сюда грузы, не проходящие через официальный космопорт.',7,31),
 ('commenor','smugglers_cut','Контрабандный проход','Скрытая развилка ведёт в тесное ущелье за торговыми трассами. В скальных нишах оборудованы дозорные площадки и замаскированные стоянки.',8,36),
 ('commenor','mountain_transshipment','Горный перевалочный комплекс','Многоярусные ангары врезаны в стену высокого плато. Захватившая комплекс банда перебрасывает добычу между наземными караванами и грузовыми челноками.',9,41),
 ('commenor','sealed_cargo_vault','Запечатанное грузовое хранилище','Бронированные секции скрывают самые ценные грузы нелегального маршрута. Наёмники охраняют внутренние шлюзы вместе с перепрограммированными машинами досмотра.',10,46),
 ('ralltiir','commercial_landing','Посадочная площадка торгового квартала','Посадочные опоры стоят у края большого делового района. В стороне от охраняемых проспектов тянутся служебные дворы и пустующие транспортные секции.',1,1),
 ('ralltiir','service_courtyards','Служебные дворы','За фасадами контор проходят кабельные каналы и дороги инкассации. Грабители используют технические ниши для наблюдения за ценными перевозками.',2,6),
 ('ralltiir','marble_foothills','Мраморные предгорья','Светлые склоны испещрены старыми каменоломнями. Между брошенными блоками проложены звериные тропы и обходные пути контрабандистов.',3,11),
 ('ralltiir','quarry_steps','Ступени старого карьера','Пыльные уступы спускаются к дну глубокой выработки. На нижних уровнях продолжают двигаться машины, давно потерявшие связь с диспетчером.',4,16),
 ('ralltiir','marsh_causeway','Насыпь через топи','Узкая насыпь пересекает сырые низины вдали от городских дорог. Из зарослей видны обломки грузовых платформ, оставленных после нескольких налётов.',5,21),
 ('ralltiir','closed_depository','Закрытый депозитарий','Выведенное из эксплуатации хранилище окружено высокими стенами. Вскрывшие его налётчики восстановили часть системы защиты и теперь скрываются за чужими запорами.',6,26),
 ('ralltiir','highland_galleries','Горные галереи','Старые транспортные тоннели проходят сквозь мраморный массив. Грохот карьерных машин смешивается с рычанием зверей, устроивших логова у боковых выходов.',7,31),
 ('ralltiir','reserve_vaults','Резервные сейфовые секции','Несколько подземных залов соединены переходами с независимыми шлюзами. Похитители ценностей замкнули охранные цепи и превратили каждый коридор в отдельный рубеж.',8,36),
 ('ralltiir','security_control','Узел охранного управления','За бронированными дверями сходятся линии закрытого депозитария. Перехваченные системы направляют автономную охрану против любого незнакомого посетителя.',9,41),
 ('ralltiir','deep_repository','Глубинное хранилище','Последние секции старого комплекса вырублены глубоко в скале. Здесь укрылись организаторы налётов, окружив награбленное тяжёлыми охранными автоматами.',10,46),
 ('humbarine','industrial_landing','Промышленная посадочная площадка','Между высокими производственными корпусами расположены грузовые опоры. На нижних настилах лежат разобранные контейнеры и детали, исчезнувшие из портовых ведомостей.',1,1),
 ('humbarine','scrap_yards','Дворы металлического лома','Пакеты металла образуют тесные проходы между старыми цехами. Сборщики краденых деталей защищают здесь свои мастерские от случайных свидетелей.',2,6),
 ('humbarine','utility_tunnels','Коммуникационные тоннели','Под рабочими кварталами тянутся коллекторы и кабельные трассы. В тёплых нишах обосновались зверьки, а боковые выходы заняли банды скупщиков.',3,11),
 ('humbarine','abandoned_assembly','Покинутый сборочный цех','Остановленные конвейеры пересекают огромный производственный зал. Некоторые сварочные машины продолжают повторять операции, не замечая людей на своём пути.',4,16),
 ('humbarine','old_drydocks','Старые сборочные доки','Каркасы малых судов стоят под проржавевшими грузовыми кранами. Нелегальные мастерские снимают уцелевшие узлы и возвращают к работе опасную технику.',5,21),
 ('humbarine','casting_channels','Литейные каналы','Промышленные мостки проходят над пустыми желобами и остывшими чашами. Подсобные печи снова разогреты, но управляющие системы работают с серьёзными сбоями.',6,26),
 ('humbarine','freight_lift_spine','Магистраль грузовых лифтов','Шахты подъёмников связывают несколько заброшенных ярусов города. На каждой остановке устроены укреплённые пункты перегрузки похищенного оборудования.',7,31),
 ('humbarine','sealed_fabricators','Закрытые производственные линии','За шумозащитными перегородками работают самодельные сборочные цепочки. Захватившая цехи группа выпускает детали для оружия и тщательно охраняет оборудование.',8,36),
 ('humbarine','reactor_service_ring','Сервисное кольцо энергоблока','Кольцевые коридоры окружают старый промышленный источник питания. Аварийные сигналы пробуждают тяжёлые машины, которые не признают действующих кодов обслуживания.',9,41),
 ('humbarine','armored_foundry','Бронированный литейный комплекс','Мощные ворота закрывают внутренние цехи нелегального производства. Между печами патрулируют перепрограммированные грузовые и охранные машины.',10,46),
 ('neimoidia','misty_landing','Посадочная площадка в тумане','Низкие грузовые опоры возвышаются над влажными полями. За огнями площадки исчезают в тумане дороги к хозяйствам и складским павильонам.',1,1),
 ('neimoidia','fungus_fields','Грибные поля','Под навесами тянутся ряды крупных грибных культур. Заброшенные участки заросли так густо, что между ними легко скрываются хищники и похитители урожая.',2,6),
 ('neimoidia','hive_outskirts','Окраины колоний насекомых','Тёплые земляные насыпи прорезаны многочисленными ходами. Повреждённые ограждения больше не удерживают крупных насекомых у хозяйственных участков.',3,11),
 ('neimoidia','humid_groves','Влажные рощи','Широкие кроны удерживают туман над лесными тропами. В зарослях скрыты стоянки перевозчиков, вывозящих похищенные грузы в обход торговых постов.',4,16),
 ('neimoidia','harvest_depots','Склады урожая','Длинные хранилища разделены рельсами погрузочных машин. Заблокированные ворота и снятые опознавательные метки выдают склады нелегальных скупщиков.',5,21),
 ('neimoidia','irrigation_channels','Оросительные каналы','Каменные переходы соединяют шлюзы и насосные станции. Обслуживающие дроиды продолжают расчистку по испорченным командам, не различая засоры и живые цели.',6,26),
 ('neimoidia','overgrown_hatcheries','Заросшие питомники','Покинутые хозяйственные павильоны поглощены грибными наростами. Крупные насекомые защищают гнёзда, а охотники за редкими образцами разбили рядом свои лагеря.',7,31),
 ('neimoidia','canopy_routes','Тропы под кронами','Влажные настилы скрываются под сплошным лесным пологом. По этим маршрутам вывозят запретные партии товаров, оставляя дозоры у каждой развилки.',8,36),
 ('neimoidia','processing_vaults','Закрытые перерабатывающие камеры','Герметичные залы старого хозяйства переоборудованы под тайные склады. Автоматика поддерживает влажность и температуру, пока охрана следит за внутренними проходами.',9,41),
 ('neimoidia','hidden_trade_compound','Тайный торговый комплекс','За неприметными воротами среди рощ расположен укреплённый перевалочный двор. Его хозяева собрали похищенную технику и вооружённых сообщников для защиты своего промысла.',10,46)
) AS v(planet_code,code,name,description,position,recommended_level) JOIN planets p ON p.code=v.planet_code
ON CONFLICT (planet_id,code) DO NOTHING;

-- Imperial holdings: Dathomir, Saleucami, Sriluur and Dac.
INSERT INTO locations(planet_id,code,name,description,position,recommended_level)
SELECT p.id,v.code,v.name,v.description,v.position,v.recommended_level FROM (VALUES
 ('dathomir','forest_landing','Лесная посадочная поляна','Небольшая поляна окружена густыми деревьями и каменными выступами. За пределами сигнальных огней начинаются звериные тропы и следы чужих экспедиций.',1,1),
 ('dathomir','reed_lowlands','Тростниковые низины','Сырая почва удерживает воду между корнями и плотными зарослями. Шорохи у протоков выдают хищников, поджидающих добычу на узких сухих грядах.',2,6),
 ('dathomir','beast_trails','Тропы диких зверей','Продавленные в густом подлеске проходы ведут к старым водопоям. Браконьеры расставили здесь ловушки и следят за движением крупных животных.',3,11),
 ('dathomir','stone_hollows','Каменные ложбины','Между лесистыми склонами лежат глубокие каменные складки. В пещерах скрываются мелкие хищники, а на уступах оставлено неисправное экспедиционное оборудование.',4,16),
 ('dathomir','poacher_stockade','Браконьерский загон','Грубые ограждения окружают клетки и разборные посадочные опоры. Вооружённые ловцы охраняют пойманных зверей и снаряжение для вывоза добычи.',5,21),
 ('dathomir','ancient_terraces','Древние каменные террасы','Под корнями деревьев проступают ровные ступени неизвестного сооружения. Искатели ценностей пробили несколько проходов и оставили сторожевые машины у раскопов.',6,26),
 ('dathomir','dry_gorge','Сухое ущелье','Лес уступает место выжженным скалам и пыльным руслам. У немногочисленных тенистых ниш сходятся следы крупных зверей и колеи экспедиционных платформ.',7,31),
 ('dathomir','sealed_star_ruins','Руины звёздного святилища','Древние стены сохранили знаки давно исчезнувшей цивилизации. Внешние залы заняты нелегальными раскопщиками, но проходы в глубину по-прежнему запечатаны.',8,36),
 ('dathomir','rancor_ravine','Овраг ранкоров','Широкие следы и обломанные стволы отмечают подход к нескольким логовам. Браконьеры обходят дно оврага по скалам, где расставлены тяжёлые ловчие машины.',9,41),
 ('dathomir','overgrown_precinct','Заросший древний двор','Остатки монументальных стен почти скрылись среди корней и каменных обвалов. Крупные звери заняли внутренние площадки, а упорные расхитители продолжают спорить с ними за доступ к руинам.',10,46),
 ('saleucami','crater_landing','Посадочная площадка в кратере','Грузовые площадки стоят у края плодородной впадины. Над ними поднимается сухой каменный вал, за которым дороги расходятся к оазисам и небольшим поселениям.',1,1),
 ('saleucami','oasis_gardens','Окраины оазисных садов','Полосы возделанной земли сменяются густыми зарослями у воды. На покинутых участках прячутся звери и налётчики, выбирающие момент для нападения на перевозчиков.',2,6),
 ('saleucami','dry_caldera','Сухая кальдера','Слои светлой пыли покрывают дно давно остывшей впадины. Каменные гряды дают укрытие хищникам и скрывают стоянки грабителей караванов.',3,11),
 ('saleucami','thermal_springs','Термальные источники','Тёплые потоки пробиваются между каменными чашами и влажными зарослями. Старые обслуживающие машины движутся вдоль трубопроводов, потеряв связь с поселением.',4,16),
 ('saleucami','crater_lake','Берег кратерного озера','Вода заполнила глубокую впадину под крутыми стенами. Между заросшими пристанями проложены тайные пути, которыми пользуются перевозчики краденых товаров.',5,21),
 ('saleucami','desert_relay','Пустынный перевалочный пункт','Несколько укрытых от солнца ангаров стоят на пересечении старых дорог. Банда перехватчиков превратила бывшую стоянку караванов в место сбора добычи.',6,26),
 ('saleucami','geothermal_passages','Геотермальные проходы','Технические галереи огибают горячие трещины в глубине кратера. Повреждённая автоматика открывает клапаны без предупреждения и направляет ремонтные машины против посетителей.',7,31),
 ('saleucami','jungled_crater','Кратер густых зарослей','Высокие стены удерживают влагу над тесным зелёным миром. Внутри прячутся хищники и лагеря налётчиков, связанные едва заметными лесными тропами.',8,36),
 ('saleucami','captured_power_station','Захваченная теплостанция','Укреплённый узел снабжает энергией скрытые убежища в соседних кратерах. Его новые хозяева оградили машинные залы баррикадами и выставили вооружённые дозоры.',9,41),
 ('saleucami','caldera_redoubt','Укрепление на краю кальдеры','Высокие стены старого промышленного узла контролируют дороги между оазисами. Внутренние дворы заняты наёмниками и перепрограммированной тяжёлой техникой.',10,46),
 ('sriluur','dust_landing','Посадочная площадка в пыли','Песчаный ветер проносится между низкими посадочными опорами. За защищённой зоной лежат дороги к торговым дворам и каменным укрытиям пустыни.',1,1),
 ('sriluur','caravan_courts','Караванные дворы','Невысокие стены окружают стоянки перевозчиков и склады припасов. На заброшенных задних дворах встречаются скупщики добычи и грабители пустынных дорог.',2,6),
 ('sriluur','dry_canyons','Сухие каньоны','Узкие расселины разрезают пустынное плато. Между отвесными стенами сохраняется тень, привлекающая зверей и скрывающая небольшие засады.',3,11),
 ('sriluur','obsidian_ridges','Обсидиановые гряды','Острые тёмные выступы поднимаются из песка целыми рядами. Неровные проходы ведут к тайникам, где вооружённые отряды прячут похищенное снаряжение.',4,16),
 ('sriluur','mineral_flats','Минеральные пустоши','Светлая корка покрывает низины вокруг едких водоёмов. Старые добывающие машины оставили в ней глубокие колеи, которыми теперь пользуются налётчики.',5,21),
 ('sriluur','abandoned_smelters','Покинутые плавильни','Низкие промышленные корпуса стоят у выработанных залежей. Часть печей снова запущена, но их механическая обслуга действует по повреждённым командам.',6,26),
 ('sriluur','caustic_sea_cliffs','Утёсы над едким морем','Каменная тропа поднимается над берегом неприветливого моря. Укрытые от ветра уступы заняты тайными наблюдателями и гнездовьями местных хищников.',7,31),
 ('sriluur','smuggler_basin','Котловина контрабандистов','Высокие гряды скрывают посадочные места и разборные склады. Из котловины выходят несколько узких дорог, каждую из которых охраняют вооружённые сообщники.',8,36),
 ('sriluur','raider_citadel','Цитадель налётчиков','Над пустынным проходом возвышается укрепление из тёмного камня и металла. Его хозяева собирают дань с караванов и держат под охраной захваченные машины.',9,41),
 ('sriluur','volcanic_stronghold','Крепость у вулканического разлома','Массивные стены опираются на древние застывшие потоки. Внутренние мастерские снабжают оружием отряды, контролирующие дальние пустынные маршруты.',10,46),
 ('dac','floating_landing','Плавучая посадочная платформа','Широкий настил поднимается и опускается вместе с океанской зыбью. За грузовыми опорами начинаются причалы и служебные мостки, открытые морскому ветру.',1,1),
 ('dac','mooring_walkways','Причальные мостки','Цепочка настилов связывает грузовые понтоны у края поселения. Под укрытиями прячутся похитители снабжения, а из воды иногда выбираются прибрежные звери.',2,6),
 ('dac','reef_service_deck','Настилы над рифом','Ремонтные площадки стоят над мелководной грядой. Волны захлёстывают нижние ступени, где оставлены неисправные машины для работы с затонувшими грузами.',3,11),
 ('dac','closed_pump_station','Закрытая насосная станция','Сухие коридоры соединяют машинные отсеки за прочными переборками. Заблокированные системы допуска направляют обслуживание против любого, кто входит через старые шлюзы.',4,16),
 ('dac','salvage_pontoons','Понтоны подъёма грузов','На плавучих опорах сложены извлечённые из воды обломки и контейнеры. Вооружённые сборщики присвоили площадку и охраняют свои находки вместе с переделанными дроидами.',5,21),
 ('dac','sealed_reef_gallery','Герметичная рифовая галерея','За прозрачными секциями сухого перехода видны кораллы и морские течения. Внутренние посты захвачены налётчиками, перерезавшими связь с остальной станцией.',6,26),
 ('dac','storm_platform','Штормовая грузовая платформа','Высокие волнорезы прикрывают настилы удалённого перегрузочного узла. Между закреплёнными контейнерами устроены укрытия банды, перехватывающей морские грузы.',7,31),
 ('dac','submerged_drydock','Сухой док под водой','Герметичный док соединён с поверхностью защищёнными лифтами. У боковых шлюзов стоят машины для подъёма тяжестей, а служебные отсеки заняты вооружёнными мародёрами.',8,36),
 ('dac','pressure_control','Узел герметизации','Кольцевые проходы связывают приводы переборок и аварийные насосы. Охранные автоматы удерживают этот узел по чужим командам, закрывая доступ к захваченным секциям.',9,41),
 ('dac','sealed_ocean_depot','Закрытый океанский склад','Глубокие сухие отсеки защищены несколькими независимыми шлюзами. Главари морских налётчиков укрыли здесь добычу и усилили охрану тяжёлыми ремонтными машинами.',10,46)
) AS v(planet_code,code,name,description,position,recommended_level) JOIN planets p ON p.code=v.planet_code
ON CONFLICT (planet_id,code) DO NOTHING;

